import React from "react";
import styled from "styled-components";

const TableContainer = styled.div`
  width: 100%;
  background: white;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 30px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow-x: auto;
`;

const Title = styled.h3`
  font-size: 40px;
  font-weight: bold;
  margin-bottom: 30px;
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
`;

const Th = styled.th`
  background: #d6d6d6;
  color: black;
  padding: 10px;
  text-align: left;
`;

const Td = styled.td`
  border: 1px solid #ddd;
  padding: 10px;
`;

const VirulenceTable = ({ data }) => {
  if (!data || data.length === 0) {
    return <p>No data available</p>;
  }

  const rows = data.split("\n").map((row) => row.split(","));
  let headers = rows[0];
  let body = rows.slice(1);

  // Xác định cột cần loại bỏ
  const excludeColumns = ["COVERAGE_MAP", "DATABASE"];
  const excludeIndexes = headers
    .map((col, index) => (excludeColumns.includes(col) ? index : -1))
    .filter((index) => index !== -1);

  // Cập nhật headers: thêm "STT" vào đầu và loại bỏ cột không cần thiết
  headers = ["STT", ...headers.filter((_, index) => !excludeIndexes.includes(index))];

  // Cập nhật body: thêm số thứ tự và loại bỏ cột không cần thiết
  body = body.map((row, rowIndex) => [
    rowIndex + 1, // Số thứ tự
    ...row.filter((_, index) => !excludeIndexes.includes(index)),
  ]);

  return (
    <TableContainer>
      <Title>Virulence Data</Title>
      <Table>
        <thead>
          <tr>
            {headers.map((header, index) => (
              <Th key={index}>{header}</Th>
            ))}
          </tr>
        </thead>
        <tbody>
          {body.map((row, rowIndex) => (
            <tr key={rowIndex}>
              {row.map((cell, cellIndex) => (
                <Td key={cellIndex}>{cell}</Td>
              ))}
            </tr>
          ))}
        </tbody>
      </Table>
    </TableContainer>
  );
};

export default VirulenceTable;
